static const fractal_module_descriptor summary_desc={1,1,"fractal.analyzer.escape-classification-summary","Escape and classification summary",FRACTAL_MODULE_ANALYZER,FRACTAL_CAP_ANALYZER_COMPATIBLE_FIELD|FRACTAL_CAP_ANALYZER_PRESERVES_FIELD_VALUES|FRACTAL_CAP_ANALYZER_CANCELLATION|FRACTAL_CAP_ANALYZER_PRODUCES_RECORDS|FRACTAL_CAP_ANALYZER_WHOLE_FIELD,true};
const fractal_analyzer_vtable fractal_analyzer_escape_classification_summary={&summary_desc,summary_validate,summary_begin,summary_process,common_finish,common_abort};

