static void encode_histogram(fractal_analysis_record*r,const fractal_iteration_histogram_v1*h){uint64_t values[7]={h->eligible_samples,h->excluded_samples,h->total_samples,h->minimum_iteration,h->maximum_iteration,h->summed_iterations,h->overflow_bin_count};unsigned i;memset(r,0,sizeof(*r));r->type_id=FRACTAL_ANALYSIS_RECORD_ITERATION_HISTOGRAM;r->schema_version=1;r->payload_size=HISTOGRAM_PAYLOAD_SIZE;for(i=0;i<64;i++)put_u64(r->payload+i*8u,h->bins[i]);for(i=0;i<7;i++)put_u64(r->payload+512u+i*8u,values[i]);r->payload[568]=(unsigned char)h->histogram_valid;}
static fractal_result histogram_process(fractal_analyzer_state*s,const fractal_field_view*in,fractal_mutable_field_view*out,fractal_field_view*final,const fractal_cancellation*c){fractal_iteration_histogram_v1 h={0};uint32_t x,y;uint64_t expected;if(!s||s->phase!=1||!final||out||fractal_field_view_validate(in,sizeof(fractal_point_result_compact))!=FRACTAL_OK)return FRACTAL_ERROR_INVALID_ARGUMENT;expected=(uint64_t)in->descriptor.width*in->descriptor.height;if(c&&c->requested)return summary_fail(s,FRACTAL_ERROR_CANCELLED,true);for(y=0;y<in->descriptor.height;y++){if(c&&c->requested)return summary_fail(s,FRACTAL_ERROR_CANCELLED,true);for(x=0;x<in->descriptor.width;x++){const fractal_point_result_compact*p=(const fractal_point_result_compact*)((const unsigned char*)in->data+(size_t)y*in->descriptor.stride)+x;bool eligible;if(!add_u64(&h.total_samples,1)||!add_u64(&s->result.samples_examined,1))return summary_fail(s,FRACTAL_ERROR_INVALID_SPEC,false);switch(p->classification){case FRACTAL_CLASS_ESCAPED:case FRACTAL_CLASS_BOUNDED:case FRACTAL_CLASS_UNRESOLVED:eligible=true;break;case FRACTAL_CLASS_CANCELLED:case FRACTAL_CLASS_FAILED:eligible=false;break;default:return summary_fail(s,FRACTAL_ERROR_INVALID_SPEC,false);}if(!eligible){if(!add_u64(&h.excluded_samples,1))return summary_fail(s,FRACTAL_ERROR_INVALID_SPEC,false);continue;}if(!h.histogram_valid){h.minimum_iteration=h.maximum_iteration=p->steps;h.histogram_valid=true;}else{if(p->steps<h.minimum_iteration)h.minimum_iteration=p->steps;if(p->steps>h.maximum_iteration)h.maximum_iteration=p->steps;}if(!add_u64(&h.eligible_samples,1)||!add_u64(&h.summed_iterations,p->steps)||!add_u64(&h.bins[fractal_iteration_histogram_bucket_v1(p->steps)],1))return summary_fail(s,FRACTAL_ERROR_INVALID_SPEC,false);}}h.overflow_bin_count=h.bins[63];if(h.total_samples!=expected||h.eligible_samples+h.excluded_samples!=h.total_samples)return summary_fail(s,FRACTAL_ERROR_INVALID_SPEC,false);encode_histogram(&s->result.records[0],&h);{char canonical[4096];size_t length;if(fractal_analysis_record_serialize(&s->result.records[0],canonical,sizeof(canonical),&length)!=FRACTAL_OK)return summary_fail(s,FRACTAL_ERROR_INVALID_SPEC,false);s->result.records[0].identity=hash_bytes(canonical,length);s->result.identity=s->result.records[0].identity;}*final=*in;s->result.records_produced=1;s->result.output_field_checksum=fractal_checksum64(in->data,in->descriptor.stride*in->descriptor.height);s->result.field_preserved=s->result.output_field_checksum==s->result.source_field_checksum;s->result.result=FRACTAL_OK;s->phase=2;return FRACTAL_OK;}
static const fractal_module_descriptor histogram_desc={1,1,"fractal.analyzer.iteration-histogram","Fixed-schema iteration histogram",FRACTAL_MODULE_ANALYZER,FRACTAL_CAP_ANALYZER_COMPATIBLE_FIELD|FRACTAL_CAP_ANALYZER_PRESERVES_FIELD_VALUES|FRACTAL_CAP_ANALYZER_CANCELLATION|FRACTAL_CAP_ANALYZER_PRODUCES_RECORDS|FRACTAL_CAP_ANALYZER_WHOLE_FIELD,true};
const fractal_analyzer_vtable fractal_analyzer_iteration_histogram={&histogram_desc,histogram_validate,histogram_begin,histogram_process,common_finish,common_abort};
